# region: intake
def intake(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: render
def render(xs, limit=12):
    return [v if v <= limit else limit for v in xs]

# region: digest
def digest(xs, factor=3):
    return [v * factor for v in xs]

# region: gather
def gather(xs):
    n = len(xs) - 1
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': max(xs) if xs else 0}

# region: shape
def shape(summary, name='alpha'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return shape(gather(digest(render(intake(raw)))))

